mapper.select:
SELECT bb.bill_id AS billId, bbd.item_type AS itemType, bbd.item_id AS itemId, bbd.executor_id AS executorId, (bbd.quantity*bbd.price-bbd.discount_amount) AS receivableWorkload, bbd.quantity AS quantity,
IFNULL(bbp.received_amount,0) AS totalReceivedWorkload,
bbd.received_amount AS receivedWorkload, bb.actual_amount AS actualWorkload FROM base_bill_detail bbd LEFT JOIN base_bill bb ON bb.bill_id = bbd.bill_id
LEFT JOIN ( SELECT SUM(received_amount) AS received_amount, bill_id, payee_date FROM base_bill_pay WHERE DATE_FORMAT(payee_date,'%Y%m%d')=#{payeeDate} ) bbp ON bbp.bill_id = bb.bill_id
AND bb.bill_date is not null AND bb.org_id = #{orgId}
AND DATE_FORMAT(bb.bill_date, '%Y%m%d') = #{billDate}
AND DATE_FORMAT(bbp.payee_date,'%Y%m%d')=#{payeeDate}
AND bbd.executor_id in
#{item}
